// Fixture-only acceptance command. All extension code is generated by the installed testing export.
import { createGozar } from '@tnunamak/gozar';
import { fakeRegistry } from '@tnunamak/gozar/testing';
import { renderScreen } from './remote-access-screen.mjs';
import net from 'node:net';
import { randomBytes } from 'node:crypto';
import { mkdir, mkdtemp, writeFile, readFile, rm } from 'node:fs/promises';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const cli = fileURLToPath(import.meta.resolve('@tnunamak/gozar/bin/gozar.mjs'));
function runCli(args, input) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [cli, ...args], { stdio: ['pipe', 'pipe', 'pipe'] });
    let stdout = '', stderr = '';
    child.stdout.on('data', chunk => stdout += chunk); child.stderr.on('data', chunk => stderr += chunk);
    child.once('error', reject); child.once('exit', code => code === 0 ? resolve({ stdout, stderr }) : reject(new Error(`Fixture CLI failed (${code}): ${stderr}`)));
    child.stdin.end(input);
  });
}
function exchange(origin, bytes) {
  const endpoint = new URL(origin);
  return new Promise((resolve, reject) => {
    const socket = net.connect(Number(endpoint.port), endpoint.hostname), chunks = [];
    const timer = setTimeout(() => { socket.destroy(); reject(new Error('Fixture exchange timed out')); }, 2000);
    socket.once('connect', () => socket.end(bytes)); socket.on('data', chunk => chunks.push(chunk));
    socket.once('error', error => { clearTimeout(timer); reject(error); });
    socket.once('end', () => { clearTimeout(timer); resolve(Buffer.concat(chunks)); });
  });
}

await mkdir(join(homedir(), '.tmp'), { recursive: true });
const home = await mkdtemp(join(homedir(), '.tmp', 'gz-'));
const app = net.createServer({allowHalfOpen:true}, socket => socket.pipe(socket));
await new Promise(resolve => app.listen(0, '127.0.0.1', resolve));
let registry, api, route;
try {
  const id = `fixture-${randomBytes(8).toString('hex')}`, secret = `canary-${randomBytes(24).toString('hex')}`;
  const disclosure = { revision: 'fixture-input', text: 'Fixture input only', links: [] };
  const facts = [false, 0, '', null].map((value, index) => ({ id: `novel-${index}`, label: `Novel ${index}`, value, known: index !== 3,
    ...(index === 3 ? { reason: 'needs-provider-call' } : {}), group: 'novel-group', affectsConsent: true, source: 'fixture-data', asOf: null }));
  registry = await fakeRegistry({ id, label: 'New fixture provider', kinds: ['attached'], reach: 'this-device', transport: 'tcp', proofProtocol: 'echo', dir: join(home, 'registry'), facts,
    setupActions: [{ id: 'credential', kind: 'provide-secret', label: 'Fixture credential', secretLabel: 'Fixture credential', help: 'Fixture credential is stored privately', required: true, digest: 'fixture-input', disclosure }] });
  const manifest = join(home, 'registry.json'), queryFile = join(home, 'query.json'), approvalFile = join(home, 'approval.json');
  await writeFile(manifest, JSON.stringify(registry.manifest));
  const query = { schemaVersion: 1, owner: 'fixture-consumer', home, target: `127.0.0.1:${app.address().port}`, usage: { kind: 'attached' },
    requirements: { reach: 'this-device', transport: 'tcp', payloadAccess: 'allow-provider', address: 'any', setup: 'allow', protocols: [] } };
  await writeFile(queryFile, JSON.stringify(query));
  const flags = ['--registry-file', manifest, '--registry-root', registry.root];
  const before = JSON.parse((await runCli(['catalog', '--query-file', queryFile, '--json', ...flags])).stdout);
  if (before.candidates[0].candidateToken !== null) throw new Error('Missing required input did not block consent');
  const action = before.candidates[0].configuration.actions[0];
  await writeFile(approvalFile, JSON.stringify({kind:'setup',consentFactsDigest:action.consent.consentFactsDigest,digest:action.digest,disclosureRevision:action.disclosure.revision}), { mode: 0o600 });
  const setup = await runCli(['setup', action.id, '--prompt', '--query-file', queryFile, '--provider-id',before.candidates[0].providerId,'--approval-file', approvalFile, '--home', home, '--json', ...flags], `${secret}\n`);
  api = createGozar({ manifest, root: registry.root });
  const catalog = await api.catalogRoutes(query), choice = catalog.candidates[0];
  const screen = renderScreen(catalog);
  route = await api.expose({ ...query, wait: 'verified', approval: {kind:'route',consentFactsDigest:choice.consentFactsDigest,candidateToken:choice.candidateToken,disclosureRevision:choice.disclosure.revision} });
  const bytes = Buffer.from([0, 255, 13, 10, 128, 65]);
  if (!(await exchange(route.origin, bytes)).equals(bytes)) throw new Error('Post-proof forwarding changed bytes');
  const status = await api.routeStatus({ home, handle: route.handle });
  if (status.verification.checkedAt !== route.verification.checkedAt) throw new Error('Status stamped retained proof as fresh');
  if (!(await exchange(route.origin, bytes)).equals(bytes)) throw new Error('Status disrupted application forwarding');
  const closed = await api.closeRoute({ home, handle: route.handle, mode: 'remove' });
  await api.closeRoute({ home, handle: route.handle, mode: 'remove' });
  let ownedStillOpen = false;
  try { await exchange(route.origin, bytes); ownedStillOpen = true; } catch { /* independently observed absence */ }
  const foreignPreserved = (await exchange(`tcp://127.0.0.1:${app.address().port}`, bytes)).equals(bytes);
  if (ownedStillOpen || !foreignPreserved || closed.cleanup.state !== 'confirmed') throw new Error('Independent resource cleanup check failed');
  const events = (await readFile(join(registry.root, 'providers', id, 'events.jsonl'), 'utf8')).trim().split('\n').map(line => JSON.parse(line).event);
  const result = { fixtureOnly: true, providerId: id, events, facts: choice.facts, inputRequirements: choice.configuration.inputRequirements, screen,
    proof: route.verification, cleanup: closed.cleanup, resourceLedger: { ownedAfter: [], foreignPreserved }, statusPreservedProofTime: true };
  const output = JSON.stringify(result);
  if ([output, setup.stdout, setup.stderr].some(text => text.includes(secret))) throw new Error('Fixture secret escaped intake');
  console.log(output);
} finally {
  if (route && api) await api.closeRoute({ home, handle: route.handle, mode: 'remove' }).catch(() => {});
  await new Promise(resolve => app.close(resolve));
  await registry?.cleanup(); await rm(home, { recursive: true, force: true });
}
